// ============================================================
//  Nodo "Construir Reporte HTML" — RealtyPlus Nexus
//  Transforma el payload de /expansion en un correo HTML
//  con la marca RealtyPlus + un adjunto .html de fidelidad total.
//  Modo de ejecución: "Run Once for All Items".
// ============================================================

// ── CONFIGURACIÓN (editar estas 3 líneas) ───────────────────
const DEST = "jefatura@realtyplus.es";          // <-- correo de la jefatura
const LOGO = "https://realtyplus-nexus.vercel.app/realtyplus-logo.png";
const NAVY = "#003366";
const RED  = "#cc0000";
// ────────────────────────────────────────────────────────────

// El webhook entrega el cuerpo en .json.body; si llega plano, usar .json
const p = ($input.first().json && $input.first().json.body) || $input.first().json || {};
const etiquetas = Array.isArray(p.etiquetas) ? p.etiquetas : [];

const esc = (s) => String(s ?? "")
  .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
  .replace(/\n/g, "<br>");

const fmtTs = (iso) => {
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return "";
  return d.toLocaleDateString("es-ES", { day: "2-digit", month: "2-digit", year: "2-digit" })
    + " " + d.toLocaleTimeString("es-ES", { hour: "2-digit", minute: "2-digit" });
};
const fmtDate = (iso) => {
  if (!iso) return "—";
  const d = new Date(iso);
  return isNaN(d.getTime()) ? "—"
    : d.toLocaleDateString("es-ES", { day: "2-digit", month: "2-digit", year: "numeric" });
};

const hoy = new Date().toLocaleDateString("es-ES", { day: "2-digit", month: "long", year: "numeric" });

// ── KPIs globales ───────────────────────────────────────────
const totalLeads = p.total_leads ?? etiquetas.reduce((a, t) => a + (t.total_leads || 0), 0);
const totalMsgs  = p.total_mensajes ?? 0;
const respondieron = etiquetas.reduce((a, t) => a + (t.respondieron || 0), 0);
const tasa = totalLeads > 0 ? Math.round((respondieron / totalLeads) * 100) : 0;

// ── Tarjeta de un lead con su conversación ──────────────────
const buildLead = (l, tagColor) => {
  const msgs = Array.isArray(l.conversacion) ? l.conversacion : [];
  const env = l.mensajes_enviados ?? msgs.filter((m) => m.direccion === "outbound").length;
  const rec = l.mensajes_recibidos ?? msgs.filter((m) => m.direccion === "inbound").length;

  const bubbles = msgs.map((m) => {
    const out = m.direccion === "outbound";
    const canal = (m.canal && m.canal !== "WhatsApp") ? `<span class="cb">${esc(m.canal)}</span>` : "";
    const txt = esc((m.contenido || "").trim());
    return `<div class="brow ${out ? "o" : "i"}"><div class="bub ${out ? "bo" : "bi"}">${canal}<div class="bx">${txt || "<em style='opacity:.4'>Media</em>"}</div><div class="bt">${fmtTs(m.fecha)}</div></div></div>`;
  }).join("");

  const etqs = (l.etiquetas || []).map((n) => `<span class="chip">${esc(n)}</span>`).join("");

  return `<div class="lead">
    <div class="lhd">
      <div class="lav" style="background:${tagColor || NAVY}">${esc((l.nombre || "?").charAt(0).toUpperCase())}</div>
      <div class="lin">
        <div class="lnm">${esc(l.nombre || "Sin nombre")}</div>
        <div class="lmt">📱 ${esc(l.telefono || "")}${l.pais ? ` · 🌍 ${esc(l.pais)}` : ""}${l.email ? ` · ✉ ${esc(l.email)}` : ""}</div>
        <div class="lbg">
          <span class="bg">${esc(l.estado || "sin estado")}</span>
          ${l.id_contacto ? `<span class="bg id">ID ${esc(l.id_contacto)}</span>` : ""}
          ${l.ha_respondido ? `<span class="bg ok">✅ Respondió</span>` : ""}
          ${l.bot_activo ? `<span class="bg bot">🤖 Bot</span>` : ""}
        </div>
      </div>
      <div class="lst">
        <div class="st"><b style="color:#16a34a">${env}</b><small>Env</small></div>
        <div class="st"><b style="color:${NAVY}">${rec}</b><small>Rec</small></div>
        <div class="st"><b>${msgs.length}</b><small>Total</small></div>
      </div>
    </div>
    ${etqs ? `<div class="erow">${etqs}</div>` : ""}
    <div class="drow">Último contacto: <b>${fmtDate(l.ultimo_contacto_at)}</b>${l.fecha_proximo_contacto ? ` · Próximo: <b>${fmtDate(l.fecha_proximo_contacto)}</b>` : ""}${l.origen ? ` · Origen: <b>${esc(l.origen)}</b>` : ""}</div>
    ${msgs.length ? `<div class="chd">💬 ${msgs.length} mensajes</div><div class="cha">${bubbles}</div>` : `<div class="nom">Sin mensajes registrados</div>`}
  </div>`;
};

// ── Secciones por etiqueta (ya vienen agrupadas en el payload) ──
const secciones = etiquetas.map((t) => {
  const leads = Array.isArray(t.leads) ? t.leads : [];
  const cards = leads.length
    ? leads.map((l) => buildLead(l, t.color)).join("")
    : `<div class="nom">Sin leads en esta etiqueta</div>`;
  return `<div class="tag">
    <div class="thd" style="border-left:5px solid ${t.color || NAVY}">
      <span class="tdot" style="background:${t.color || NAVY}"></span>
      <span class="ttl">${esc(t.nombre)}</span>
      <span class="tpill" style="background:${t.color || NAVY}1a;color:${t.color || NAVY}">${t.total_leads ?? leads.length} leads</span>
      <span class="tpill2">${t.respondieron || 0} respondieron · ${t.tasa_respuesta || 0}%</span>
    </div>
    <div class="tbd">${cards}</div>
  </div>`;
}).join("");

// ── HTML final (marca RealtyPlus) ───────────────────────────
const html = `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Reporte de Leads Etiquetados — ${hoy}</title>
<style>
*{box-sizing:border-box;margin:0;padding:0}
body{font-family:'Segoe UI',Arial,sans-serif;background:#eef1f5;color:#1f2937;font-size:13px;line-height:1.5}
.wrap{max-width:820px;margin:0 auto;background:#fff}
.ph{background:#fff;border-bottom:4px solid ${RED};padding:22px 28px;text-align:center}
.ph img{height:54px;width:auto}
.ph h1{font-size:18px;color:${NAVY};margin-top:12px;font-weight:700}
.ph p{color:#6b7280;font-size:12px;margin-top:4px}
.kpis{display:flex;flex-wrap:wrap;gap:10px;padding:18px 28px;background:${NAVY}}
.kpi{flex:1;min-width:120px;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);border-radius:8px;padding:14px;text-align:center}
.kpi b{display:block;font-size:24px;color:#fff}.kpi small{font-size:10px;color:#c7d2e0;text-transform:uppercase;letter-spacing:.5px}
.main{padding:20px 28px 36px}
.tag{border:1px solid #e2e8f0;border-radius:10px;margin-bottom:18px;overflow:hidden}
.thd{display:flex;align-items:center;gap:10px;padding:13px 16px;background:#f8fafc}
.tdot{width:12px;height:12px;border-radius:50%;flex-shrink:0}
.ttl{font-size:15px;font-weight:700;color:${NAVY};flex:1}
.tpill{padding:2px 10px;border-radius:20px;font-size:11px;font-weight:700}
.tpill2{font-size:11px;color:#6b7280}
.tbd{padding:12px}
.lead{background:#fff;border:1px solid #eef1f5;border-radius:9px;margin-bottom:10px;overflow:hidden}
.lhd{display:flex;align-items:center;gap:12px;padding:12px 14px;background:#fbfcfe}
.lav{width:38px;height:38px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:16px;font-weight:700;color:#fff;flex-shrink:0}
.lin{flex:1;min-width:0}
.lnm{font-size:14px;font-weight:700;color:#111827}
.lmt{font-size:11px;color:#6b7280;margin-top:2px}
.lbg{margin-top:5px}
.bg{display:inline-block;background:#eef1f5;color:#6b7280;padding:1px 8px;border-radius:4px;font-size:10px;font-weight:600;margin-right:4px}
.bg.id{background:#e0e7ff;color:${NAVY}}.bg.ok{background:#dcfce7;color:#16a34a}.bg.bot{background:#fef3c7;color:#b45309}
.lst{display:flex;gap:14px;flex-shrink:0;text-align:center}
.st b{display:block;font-size:16px}.st small{font-size:9px;color:#9ca3af}
.erow{padding:8px 14px;border-top:1px solid #f1f5f9}
.chip{display:inline-block;background:${NAVY}12;color:${NAVY};border:1px solid ${NAVY}33;padding:2px 9px;border-radius:20px;font-size:10px;font-weight:600;margin-right:4px}
.drow{padding:7px 14px;font-size:11px;color:#9ca3af;border-top:1px solid #f1f5f9}.drow b{color:#374151}
.nom{padding:12px 14px;color:#cbd5e1;font-style:italic}
.chd{padding:8px 14px;background:${NAVY};color:#fff;font-size:11px;font-weight:600}
.cha{background:#f6f8fb;padding:12px 14px}
.brow{display:flex;margin-bottom:7px}.brow.o{justify-content:flex-end}.brow.i{justify-content:flex-start}
.bub{max-width:74%;padding:7px 11px;border-radius:11px;word-break:break-word}
.bo{background:${NAVY};color:#fff;border-bottom-right-radius:2px}
.bi{background:#fff;color:#1f2937;border:1px solid #e2e8f0;border-bottom-left-radius:2px}
.bx{font-size:12px}.bt{font-size:10px;opacity:.6;text-align:right;margin-top:3px}
.cb{display:inline-block;background:rgba(0,0,0,.08);border-radius:3px;padding:0 4px;font-size:9px;margin-bottom:3px}
.ft{text-align:center;padding:16px;color:#9ca3af;font-size:10px;border-top:1px solid #eef1f5}
</style></head><body><div class="wrap">
<div class="ph"><img src="${LOGO}" alt="RealtyPlus — Servicios Inmobiliarios"><h1>Reporte de Leads Etiquetados</h1><p>Generado el ${hoy} · Filtro: ${esc(p.filtro || "todas")} · ${totalLeads} leads · ${totalMsgs} mensajes</p></div>
<div class="kpis">
  <div class="kpi"><b>${totalLeads}</b><small>Total leads</small></div>
  <div class="kpi"><b>${respondieron}</b><small>Respondieron</small></div>
  <div class="kpi"><b>${tasa}%</b><small>Tasa respuesta</small></div>
  <div class="kpi"><b>${etiquetas.length}</b><small>Etiquetas</small></div>
</div>
<div class="main">${secciones || '<div class="nom">No hay leads etiquetados en este envío.</div>'}</div>
<div class="ft">RealtyPlus · Servicios Inmobiliarios · Generado automáticamente por RealtyPlus Nexus · ${hoy}</div>
</div></body></html>`;

const asunto = `📋 RealtyPlus — Reporte de leads etiquetados (${p.filtro || "todas"}) · ${totalLeads} leads · ${hoy}`;

// Adjunto .html de fidelidad total (los agentes lo abren en navegador)
const fileName = `reporte-leads-${new Date().toISOString().slice(0, 10)}.html`;
const binary = await this.helpers.prepareBinaryData(Buffer.from(html, "utf-8"), fileName, "text/html");

return [{
  json: {
    to: DEST,
    subject: asunto,
    html,
    filtro: p.filtro || "todas",
    total_leads: totalLeads,
    total_mensajes: totalMsgs,
    total_etiquetas: etiquetas.length,
  },
  binary: { reporte: binary },
}];
